def quick_sort(items : Array(Int32)) : Array(Int32)
  return items.dup if items.size <= 1

  pivot = items.first
  rest = items[1..]
  smaller = rest.select { |item| item < pivot }
  equal = rest.select { |item| item == pivot }
  larger = rest.select { |item| item > pivot }

  quick_sort(smaller) + [pivot] + equal + quick_sort(larger)
end

class Graph
  getter edges : Hash(String, Array(String))

  def initialize
    @edges = Hash(String, Array(String)).new
  end

  def add_edge(from : String, to : String) : Nil
    @edges[from] ||= [] of String
    @edges[to] ||= [] of String
    @edges[from] << to
    @edges[to] << from
  end
end
